        simple_tuple: tuple = None
        tuple_of_different_types: tuple[int, float, str, bool] = None
        tuple_of_single_tuples: tuple[tuple[int], ...] = ()

    m = Model(
        empty_tuple=[],
        simple_tuple=[1, 2, 3, 4],
